import { describeWaveform } from "@siren-ui/core/accessibility";
import {
  bucketSamples,
  deriveVisibleBucketCount,
  normalizeAmplitude,
} from "@siren-ui/core/waveform";
import { developmentWarning } from "@siren-ui/core/warnings";
import { memo, useMemo, useState } from "react";
import {
  PixelRatio,
  StyleSheet,
  View,
  type LayoutChangeEvent,
  type StyleProp,
  type ViewStyle,
} from "react-native";

export type WaveformProps = {
  samples: readonly number[];
  progress?: number;
  height?: number;
  barWidth?: number;
  gap?: number;
  maximumDensity?: number;
  color?: string;
  playedColor?: string;
  accessibilityLabel?: string;
  durationMs?: number;
  reducedMotion?: boolean;
  style?: StyleProp<ViewStyle>;
  barStyle?: StyleProp<ViewStyle>;
  onLayout?: (event: LayoutChangeEvent) => void;
};

export const Waveform = memo(function Waveform({
  samples,
  progress = 0,
  height = 48,
  barWidth = 3,
  gap = 2,
  maximumDensity = 240,
  color = "#8B929E",
  playedColor = "#266EF1",
  accessibilityLabel,
  durationMs,
  style,
  barStyle,
  onLayout,
}: WaveformProps) {
  const [width, setWidth] = useState(0);
  developmentWarning(
    "waveform-height",
    height >= 24,
    "Waveform heights below 24 points can be difficult to perceive.",
  );
  const safeProgress = normalizeAmplitude(progress);
  const visible = useMemo(() => {
    const count = deriveVisibleBucketCount({
      width,
      barWidth,
      gap,
      maximumDensity,
      pixelRatio: PixelRatio.get(),
    });
    return bucketSamples(samples, count);
  }, [barWidth, gap, maximumDensity, samples, width]);

  const handleLayout = (event: LayoutChangeEvent) => {
    setWidth(event.nativeEvent.layout.width);
    onLayout?.(event);
  };

  return (
    <View
      accessible
      accessibilityRole="image"
      accessibilityLabel={
        accessibilityLabel ??
        describeWaveform({ durationMs, progress: safeProgress })
      }
      onLayout={handleLayout}
      style={[styles.root, { height, gap }, style]}
    >
      {visible.map((sample, index) => {
        const played =
          visible.length < 2
            ? safeProgress > 0
            : index / (visible.length - 1) <= safeProgress;
        return (
          <View
            key={index}
            accessible={false}
            style={[
              styles.bar,
              {
                width: barWidth,
                height: Math.max(2, sample * height),
                backgroundColor: played ? playedColor : color,
              },
              barStyle,
            ]}
          />
        );
      })}
    </View>
  );
});

const styles = StyleSheet.create({
  root: { flexDirection: "row", alignItems: "center", overflow: "hidden" },
  bar: { borderRadius: 999 },
});

import { normalizeAmplitude } from "@siren-ui/core/waveform";
import { developmentWarning } from "@siren-ui/core/warnings";
import { memo, useEffect, useRef } from "react";
import { StyleSheet, View, type StyleProp, type ViewStyle } from "react-native";
import Animated, {
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withTiming,
  type SharedValue,
} from "react-native-reanimated";
import { shouldReduceMotion, sirenEaseOut } from "../motion";

export type LiveWaveformProps = {
  sample: number;
  historySize?: number;
  paused?: boolean;
  direction?: "left-to-right" | "right-to-left";
  height?: number;
  color?: string;
  reducedMotion?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

function LiveBar({
  values,
  index,
  height,
  color,
  reducedMotion,
  recency,
  newest,
  arrival,
}: {
  values: SharedValue<number[]>;
  index: number;
  height: number;
  color: string;
  reducedMotion: boolean;
  recency: number;
  newest: boolean;
  arrival: SharedValue<number>;
}) {
  const animatedStyle = useAnimatedStyle(() => {
    const value = values.value[index] ?? 0.04;
    const arrivalScale =
      newest && !reducedMotion ? 1 + arrival.value * 0.45 : 1;
    return {
      opacity: reducedMotion
        ? 0.82
        : (0.34 + value * 0.66) * (0.56 + recency * 0.44),
      transform: [{ scaleX: arrivalScale }, { scaleY: Math.max(0.04, value) }],
    };
  }, [height, index, newest, recency, reducedMotion]);
  return (
    <Animated.View
      style={[styles.bar, { height, backgroundColor: color }, animatedStyle]}
    />
  );
}

export const LiveWaveform = memo(function LiveWaveform({
  sample,
  historySize = 48,
  paused = false,
  direction = "left-to-right",
  height = 48,
  color = "#266EF1",
  reducedMotion,
  accessibilityLabel = "Live microphone level",
  style,
}: LiveWaveformProps) {
  const safeSize = Math.max(4, Math.min(160, Math.floor(historySize)));
  const systemReducedMotion = useReducedMotion();
  const reduce = shouldReduceMotion(reducedMotion, systemReducedMotion);
  const values = useSharedValue(new Array<number>(safeSize).fill(0.04));
  const arrival = useSharedValue(0);
  const history = useRef(new Array<number>(safeSize).fill(0.04));
  developmentWarning(
    "live-history",
    historySize <= 160,
    "LiveWaveform history is capped at 160 samples to keep work bounded.",
  );

  useEffect(() => {
    history.current = new Array<number>(safeSize).fill(0.04);
    values.set(history.current);
  }, [safeSize, values]);

  useEffect(() => {
    if (paused) return;
    const next = history.current.slice(1);
    next.push(normalizeAmplitude(sample));
    history.current = next;
    arrival.set(reduce ? 0 : 1);
    if (!reduce) {
      arrival.set(withTiming(0, { duration: 180, easing: sirenEaseOut }));
    }
    values.set(
      reduce ? next : withTiming(next, { duration: 120, easing: sirenEaseOut }),
    );
  }, [arrival, paused, reduce, sample, values]);

  return (
    <View
      accessible
      accessibilityRole="image"
      accessibilityLabel={accessibilityLabel}
      accessibilityState={{ disabled: paused }}
      style={[
        styles.root,
        direction === "right-to-left" && styles.reverse,
        { height },
        style,
      ]}
    >
      <View
        pointerEvents="none"
        style={[styles.centerline, { backgroundColor: color }]}
      />
      {Array.from({ length: safeSize }, (_, index) => (
        <LiveBar
          key={index}
          values={values}
          index={index}
          height={height}
          color={color}
          reducedMotion={reduce}
          recency={index / Math.max(1, safeSize - 1)}
          newest={index === safeSize - 1}
          arrival={arrival}
        />
      ))}
    </View>
  );
});

const styles = StyleSheet.create({
  root: {
    flexDirection: "row",
    alignItems: "center",
    gap: 2,
    overflow: "hidden",
  },
  reverse: { flexDirection: "row-reverse" },
  bar: { flex: 1, minWidth: 1, borderRadius: 999 },
  centerline: {
    position: "absolute",
    left: 0,
    right: 0,
    top: "50%",
    height: StyleSheet.hairlineWidth,
    opacity: 0.2,
  },
});

import {
  decibelsToAmplitude,
  normalizeAmplitude,
} from "@siren-ui/core/waveform";
import { useCallback } from "react";
import type { SharedValue } from "react-native-reanimated";

export function appendLiveSample(
  buffer: SharedValue<number[]>,
  sample: number,
  historySize: number,
): void {
  "worklet";
  const next = buffer.value.slice(
    Math.max(0, buffer.value.length - historySize + 1),
  );
  next.push(normalizeAmplitude(sample));
  buffer.value = next;
}

export function useExpoMeteringSample(onSample: (sample: number) => void) {
  return useCallback(
    (meteringDb: number | undefined) => {
      if (meteringDb !== undefined) onSample(decibelsToAmplitude(meteringDb));
    },
    [onSample],
  );
}

import { Easing, ReduceMotion } from "react-native-reanimated";

/** Strong ease-out used for immediate, non-physical feedback. */
export const sirenEaseOut = Easing.bezier(0.23, 1, 0.32, 1);

/** Press-in is deliberately faster than the spring-backed release. */
export const sirenPressIn = {
  duration: 120,
  easing: sirenEaseOut,
  reduceMotion: ReduceMotion.System,
} as const;

/** Critically damped state transition: responsive without decorative bounce. */
export const sirenStateSpring = {
  duration: 300,
  dampingRatio: 1,
  reduceMotion: ReduceMotion.System,
} as const;

/** Momentum is reserved for gestures that were moving at release. */
export const sirenGestureSpring = {
  duration: 300,
  dampingRatio: 0.8,
  reduceMotion: ReduceMotion.System,
} as const;

export function shouldReduceMotion(
  explicit: boolean | undefined,
  system: boolean,
) {
  return explicit ?? system;
}

import { adjustableStep } from "@siren-ui/core/accessibility";
import { normalizeAmplitude } from "@siren-ui/core/waveform";
import { developmentWarning } from "@siren-ui/core/warnings";
import { useEffect, useMemo, useRef } from "react";
import {
  I18nManager,
  StyleSheet,
  View,
  type AccessibilityActionEvent,
  type LayoutChangeEvent,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, {
  interpolate,
  runOnJS,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import {
  shouldReduceMotion,
  sirenEaseOut,
  sirenPressIn,
  sirenStateSpring,
} from "../motion";
import { Waveform } from "./waveform";

export type WaveformScrubberProps = {
  samples: readonly number[];
  positionMs: number;
  durationMs: number;
  onSeekPreview?: (positionMs: number) => void;
  onSeek: (positionMs: number) => void;
  height?: number;
  disabled?: boolean;
  reducedMotion?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

export function WaveformScrubber({
  samples,
  positionMs,
  durationMs,
  onSeekPreview,
  onSeek,
  height = 52,
  disabled = false,
  reducedMotion,
  accessibilityLabel = "Audio position",
  style,
}: WaveformScrubberProps) {
  const systemReducedMotion = useReducedMotion();
  const reduce = shouldReduceMotion(reducedMotion, systemReducedMotion);
  const width = useSharedValue(1);
  const progress = useSharedValue(
    durationMs > 0 ? normalizeAmplitude(positionMs / durationMs) : 0,
  );
  const pressed = useSharedValue(0);
  const lastPreviewAt = useSharedValue(0);
  const seeking = useRef(false);
  developmentWarning(
    "scrubber-height",
    height >= 44,
    "WaveformScrubber should be at least 44 points tall for a safe touch target.",
  );

  useEffect(() => {
    if (seeking.current) return;
    const next =
      durationMs > 0 ? normalizeAmplitude(positionMs / durationMs) : 0;
    progress.set(
      reduce ? next : withTiming(next, { duration: 120, easing: sirenEaseOut }),
    );
  }, [durationMs, positionMs, progress, reduce]);

  const markSeeking = (value: boolean) => {
    seeking.current = value;
  };
  const rtl = I18nManager.isRTL;
  const gesture = useMemo(() => {
    const ratioAt = (x: number) => {
      "worklet";
      const ratio = Math.max(0, Math.min(1, x / width.get()));
      return rtl ? 1 - ratio : ratio;
    };
    const begin = () => {
      "worklet";
      pressed.set(withTiming(1, sirenPressIn));
      runOnJS(markSeeking)(true);
    };
    const finalize = () => {
      "worklet";
      pressed.set(reduce ? 0 : withSpring(0, sirenStateSpring));
      runOnJS(markSeeking)(false);
    };
    return Gesture.Race(
      Gesture.Pan()
        .enabled(!disabled)
        .minDistance(1)
        .onBegin(begin)
        .onUpdate(({ x }) => {
          const next = ratioAt(x);
          progress.set(next);
          const now = Date.now();
          if (onSeekPreview && now - lastPreviewAt.get() >= 100) {
            lastPreviewAt.set(now);
            runOnJS(onSeekPreview)(next * Math.max(0, durationMs));
          }
        })
        .onEnd(({ x }) => {
          const next = ratioAt(x);
          progress.set(next);
          runOnJS(onSeek)(next * Math.max(0, durationMs));
        })
        .onFinalize(finalize),
      Gesture.Tap()
        .enabled(!disabled)
        .onBegin(begin)
        .onEnd(({ x }) => {
          const next = ratioAt(x);
          progress.set(reduce ? next : withSpring(next, sirenStateSpring));
          runOnJS(onSeek)(next * Math.max(0, durationMs));
        })
        .onFinalize(finalize),
    );
  }, [
    disabled,
    durationMs,
    lastPreviewAt,
    onSeek,
    onSeekPreview,
    pressed,
    progress,
    reduce,
    rtl,
    width,
  ]);

  const onAccessibilityAction = (event: AccessibilityActionEvent) => {
    if (
      event.nativeEvent.actionName !== "increment" &&
      event.nativeEvent.actionName !== "decrement"
    )
      return;
    onSeek(
      adjustableStep(positionMs, durationMs, event.nativeEvent.actionName),
    );
  };

  const onLayout = (event: LayoutChangeEvent) => {
    width.set(Math.max(1, event.nativeEvent.layout.width));
  };
  const progressStyle = useAnimatedStyle(() => ({
    transform: [{ scaleX: progress.get() }],
  }));
  const thumbStyle = useAnimatedStyle(() => {
    const physicalProgress = rtl ? 1 - progress.get() : progress.get();
    return {
      opacity: interpolate(pressed.get(), [0, 1], [0.78, 1]),
      transform: [
        { translateX: physicalProgress * width.get() - 7 },
        {
          scale: reduce ? 1 : interpolate(pressed.get(), [0, 1], [0.82, 1.16]),
        },
      ],
    };
  });

  return (
    <GestureDetector gesture={gesture}>
      <View
        accessible
        accessibilityRole="adjustable"
        accessibilityLabel={accessibilityLabel}
        accessibilityValue={{
          min: 0,
          max: Math.max(0, Math.round(durationMs)),
          now: Math.round(positionMs),
          text: `${Math.round(positionMs / 1000)} seconds`,
        }}
        accessibilityActions={[
          { name: "increment", label: "Seek forward" },
          { name: "decrement", label: "Seek backward" },
        ]}
        onAccessibilityAction={onAccessibilityAction}
        onLayout={onLayout}
        style={[styles.touchArea, { minHeight: height }, style]}
      >
        <View pointerEvents="none" style={styles.track}>
          <Animated.View
            style={[
              styles.progress,
              rtl ? styles.progressRtl : styles.progressLtr,
              progressStyle,
            ]}
          />
        </View>
        <Waveform
          samples={samples}
          progress={durationMs > 0 ? positionMs / durationMs : 0}
          height={Math.max(24, height - 12)}
          reducedMotion={reduce}
        />
        <Animated.View
          pointerEvents="none"
          style={[styles.thumb, thumbStyle]}
        />
      </View>
    </GestureDetector>
  );
}

const styles = StyleSheet.create({
  touchArea: { justifyContent: "center", width: "100%" },
  track: {
    position: "absolute",
    left: 0,
    right: 0,
    height: 3,
    borderRadius: 999,
    backgroundColor: "rgba(38,110,241,0.12)",
    overflow: "hidden",
  },
  progress: {
    ...StyleSheet.absoluteFill,
    borderRadius: 999,
    backgroundColor: "rgba(38,110,241,0.38)",
  },
  progressLtr: { transformOrigin: "left center" },
  progressRtl: { transformOrigin: "right center" },
  thumb: {
    position: "absolute",
    left: 0,
    width: 14,
    height: 14,
    borderRadius: 7,
    backgroundColor: "#266EF1",
    borderWidth: 2,
    borderColor: "#FFFFFF",
    shadowColor: "#15171A",
    shadowOpacity: 0.2,
    shadowRadius: 5,
    shadowOffset: { width: 0, height: 2 },
    elevation: 3,
  },
});

import { Easing, ReduceMotion } from "react-native-reanimated";

/** Strong ease-out used for immediate, non-physical feedback. */
export const sirenEaseOut = Easing.bezier(0.23, 1, 0.32, 1);

/** Press-in is deliberately faster than the spring-backed release. */
export const sirenPressIn = {
  duration: 120,
  easing: sirenEaseOut,
  reduceMotion: ReduceMotion.System,
} as const;

/** Critically damped state transition: responsive without decorative bounce. */
export const sirenStateSpring = {
  duration: 300,
  dampingRatio: 1,
  reduceMotion: ReduceMotion.System,
} as const;

/** Momentum is reserved for gestures that were moving at release. */
export const sirenGestureSpring = {
  duration: 300,
  dampingRatio: 0.8,
  reduceMotion: ReduceMotion.System,
} as const;

export function shouldReduceMotion(
  explicit: boolean | undefined,
  system: boolean,
) {
  return explicit ?? system;
}

import { developmentWarning } from "@siren-ui/core/warnings";
import * as Haptics from "expo-haptics";
import { useEffect, useMemo } from "react";
import {
  I18nManager,
  Pressable,
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, {
  cancelAnimation,
  interpolate,
  runOnJS,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withRepeat,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import {
  shouldReduceMotion,
  sirenGestureSpring,
  sirenPressIn,
  sirenStateSpring,
} from "../motion";

export type HoldToRecordProps = {
  active: boolean;
  locked?: boolean;
  disabled?: boolean;
  cancelThreshold?: number;
  lockThreshold?: number;
  holdDelayMs?: number;
  onStart: () => void;
  onCancel: () => void;
  onLock: () => void;
  onRelease: () => void;
  label?: string;
  cancelLabel?: string;
  lockLabel?: string;
  reducedMotion?: boolean;
  style?: StyleProp<ViewStyle>;
};

function rubberBand(value: number, limit: number) {
  "worklet";
  const magnitude = Math.abs(value);
  if (magnitude <= limit) return value;
  return Math.sign(value) * (limit + (magnitude - limit) * 0.18);
}

const startHaptic = () =>
  void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Soft);
const cancelHaptic = () =>
  void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
const lockHaptic = () => void Haptics.selectionAsync();

export function HoldToRecord({
  active,
  locked = false,
  disabled = false,
  cancelThreshold = 88,
  lockThreshold = 72,
  holdDelayMs = 180,
  onStart,
  onCancel,
  onLock,
  onRelease,
  label = "Hold to record",
  cancelLabel = "Cancel recording",
  lockLabel = "Lock recording",
  reducedMotion,
  style,
}: HoldToRecordProps) {
  developmentWarning(
    "hold-target",
    cancelThreshold >= 64 && lockThreshold >= 56,
    "Hold gesture thresholds may be too small to avoid accidental actions.",
  );
  const systemReducedMotion = useReducedMotion();
  const reduce = shouldReduceMotion(reducedMotion, systemReducedMotion);
  const dragX = useSharedValue(0);
  const dragY = useSharedValue(0);
  const pressed = useSharedValue(0);
  const cancelProgress = useSharedValue(0);
  const lockProgress = useSharedValue(0);
  const cancelled = useSharedValue(false);
  const didLock = useSharedValue(false);
  const didStart = useSharedValue(false);
  const recordingPulse = useSharedValue(0);

  useEffect(() => {
    cancelAnimation(recordingPulse);
    if (!active || reduce) {
      recordingPulse.set(active ? 1 : 0);
      return;
    }
    recordingPulse.set(0);
    recordingPulse.set(withRepeat(withTiming(1, { duration: 620 }), -1, true));
    return () => cancelAnimation(recordingPulse);
  }, [active, recordingPulse, reduce]);

  const resetGesture = () => {
    "worklet";
    pressed.set(withSpring(0, sirenStateSpring));
    dragX.set(reduce ? 0 : withSpring(0, sirenGestureSpring));
    dragY.set(reduce ? 0 : withSpring(0, sirenGestureSpring));
    cancelProgress.set(withTiming(0, sirenPressIn));
    lockProgress.set(withTiming(0, sirenPressIn));
  };

  const gesture = useMemo(() => {
    const pan = Gesture.Pan()
      .enabled(!disabled && !locked)
      .manualActivation(true)
      .shouldCancelWhenOutside(false)
      .onTouchesMove((_event, stateManager) => {
        if (didStart.get()) stateManager.activate();
      })
      .onUpdate(({ translationX, translationY }) => {
        if (cancelled.get() || didLock.get()) return;
        const cancelDistance = I18nManager.isRTL ? translationX : -translationX;
        const lockDistance = -translationY;
        const cancelIntent = Math.max(0, cancelDistance);
        const lockIntent = Math.max(0, lockDistance);
        dragX.set(rubberBand(translationX, cancelThreshold));
        dragY.set(rubberBand(translationY, lockThreshold));
        cancelProgress.set(Math.min(1, cancelIntent / cancelThreshold));
        lockProgress.set(Math.min(1, lockIntent / lockThreshold));

        if (cancelIntent >= cancelThreshold && cancelIntent > lockIntent) {
          cancelled.set(true);
          runOnJS(cancelHaptic)();
          runOnJS(onCancel)();
        } else if (lockIntent >= lockThreshold && lockIntent >= cancelIntent) {
          didLock.set(true);
          runOnJS(lockHaptic)();
          runOnJS(onLock)();
        }
      });
    const longPress = Gesture.LongPress()
      .enabled(!disabled && !locked)
      .minDuration(holdDelayMs)
      .maxDistance(20)
      .shouldCancelWhenOutside(false)
      .onBegin(() => {
        pressed.set(withTiming(1, sirenPressIn));
      })
      .onStart(() => {
        didStart.set(true);
        cancelled.set(false);
        didLock.set(false);
        runOnJS(startHaptic)();
        runOnJS(onStart)();
      })
      .onEnd((_event, success) => {
        if (success && !cancelled.get() && !didLock.get()) runOnJS(onRelease)();
      })
      .onFinalize(() => {
        didStart.set(false);
        resetGesture();
      });
    return Gesture.Simultaneous(longPress, pan);
  }, [
    cancelProgress,
    cancelThreshold,
    cancelled,
    didLock,
    didStart,
    disabled,
    dragX,
    dragY,
    holdDelayMs,
    lockProgress,
    lockThreshold,
    locked,
    onCancel,
    onLock,
    onRelease,
    onStart,
    pressed,
    reduce,
  ]);

  const controlStyle = useAnimatedStyle(() => ({
    opacity: interpolate(pressed.get(), [0, 1], [1, 0.94]),
    transform: [
      { translateX: dragX.get() },
      { translateY: dragY.get() },
      {
        scale: reduce ? 1 : interpolate(pressed.get(), [0, 1], [1, 0.965]),
      },
    ],
  }));
  const glyphStyle = useAnimatedStyle(() => ({
    opacity: active ? interpolate(recordingPulse.get(), [0, 1], [0.72, 1]) : 1,
    transform: [
      {
        scale:
          active && !reduce
            ? interpolate(recordingPulse.get(), [0, 1], [0.82, 1.18])
            : 1,
      },
    ],
  }));
  const cancelGuideStyle = useAnimatedStyle(() => ({
    opacity: interpolate(pressed.get(), [0, 1], [0, 1]),
    transform: [
      {
        translateX: reduce
          ? 0
          : interpolate(cancelProgress.get(), [0, 1], [8, -8]),
      },
      { scale: interpolate(cancelProgress.get(), [0, 1], [0.96, 1.04]) },
    ],
  }));
  const lockGuideStyle = useAnimatedStyle(() => ({
    opacity: interpolate(pressed.get(), [0, 1], [0, 1]),
    transform: [
      {
        translateY: reduce
          ? 0
          : interpolate(lockProgress.get(), [0, 1], [6, -8]),
      },
      { scale: interpolate(lockProgress.get(), [0, 1], [0.96, 1.04]) },
    ],
  }));

  return (
    <View style={[styles.container, style]}>
      <View pointerEvents="none" style={styles.guides}>
        <Animated.View style={[styles.guide, cancelGuideStyle]}>
          <Text style={styles.guideArrow}>{I18nManager.isRTL ? "›" : "‹"}</Text>
          <Text style={styles.guideLabel}>Slide to cancel</Text>
        </Animated.View>
        <Animated.View style={[styles.guide, lockGuideStyle]}>
          <Text style={styles.guideArrow}>↑</Text>
          <Text style={styles.guideLabel}>Slide to lock</Text>
        </Animated.View>
      </View>
