  });
  const { snapshot } = recorder;
  useImperativeHandle(
    ref,
    () => ({
      start: recorder.start,
      stop: recorder.stop,
      cancel: recorder.cancel,
      pause: recorder.pause,
      resume: recorder.resume,
    }),
    [recorder],
  );
  if (snapshot.state === "preview" && snapshot.recording)
    return (
      <RecordingPreview
        recording={snapshot.recording}
        onDiscard={recorder.reset}
        onConfirm={onComplete}
        reducedMotion={reducedMotion}
        style={style}
      />
    );
  if (snapshot.state === "error")
    return (
      <View style={[styles.root, style]}>
        <AudioStatusIndicator
          status="error"
          label={snapshot.error?.type.replaceAll("-", " ")}
          reducedMotion={reducedMotion}
        />
        {snapshot.error?.type === "recording-interrupted" &&
        snapshot.error.partialUri ? (
          <Text selectable style={styles.message}>
            A partial recording is available at {snapshot.error.partialUri}
          </Text>
        ) : null}
        <MotionPressable
          onPress={recorder.reset}
          style={styles.action}
          reducedMotion={reducedMotion}
        >
          <Text>{labels?.retry ?? "Try again"}</Text>
        </MotionPressable>
      </View>
    );
  const active =
    snapshot.state === "recording" ||
    snapshot.state === "locked" ||
    snapshot.state === "paused";
  return (
    <View accessibilityLabel="Voice note recorder" style={[styles.root, style]}>
      <AudioStatusIndicator
        status={
          snapshot.state === "processing"
            ? "loading"
            : snapshot.state === "paused"
              ? "paused"
              : active
                ? "recording"
                : "ready"
        }
        reducedMotion={reducedMotion}
      />
      {active ? (
        <>
          <LiveWaveform
            sample={recorder.sample}
            paused={snapshot.state === "paused"}
            reducedMotion={reducedMotion}
          />
          <RecordingTimer
            durationMs={snapshot.durationMs}
            state={snapshot.state === "paused" ? "paused" : "recording"}
            warningThresholdMs={warningThresholdMs}
            maximumDurationMs={maximumDurationMs}
          />
        </>
      ) : null}
      <HoldToRecord
        active={active}
        locked={snapshot.state === "locked" || snapshot.state === "paused"}
        disabled={snapshot.state === "processing"}
        onStart={() => void recorder.start()}
        onCancel={() => void recorder.cancel()}
        onLock={recorder.lock}
        onRelease={() => void recorder.stop()}
        label={labels?.record}
        cancelLabel={labels?.cancel}
        lockLabel={labels?.lock}
        reducedMotion={reducedMotion}
      />
      {snapshot.state === "locked" || snapshot.state === "paused" ? (
        <View style={styles.row}>
          <MotionPressable
            onPress={() =>
              void (snapshot.state === "paused"
                ? recorder.resume()
                : recorder.pause())
            }
            style={styles.action}
            reducedMotion={reducedMotion}
          >
            <Text>{snapshot.state === "paused" ? "Resume" : "Pause"}</Text>
          </MotionPressable>
          <MotionPressable
            onPress={() => void recorder.stop()}
            style={styles.action}
            reducedMotion={reducedMotion}
          >
            <Text>Finish</Text>
          </MotionPressable>
        </View>
      ) : null}
    </View>
  );
});

const styles = StyleSheet.create({
  root: { padding: 16, gap: 14, borderRadius: 20, backgroundColor: "#F8F9FA" },
  row: { flexDirection: "row", gap: 8 },
  action: {
    minHeight: 44,
    paddingHorizontal: 16,
    justifyContent: "center",
    alignSelf: "flex-start",
    borderRadius: 12,
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: "#8B929E",
  },
  message: { color: "#5D6470" },
});

import {
  RecorderController,
  type RecorderSnapshot,
} from "@siren-ui/core/recorder-controller";
import type {
  SirenRecorderError,
  SirenRecording,
} from "@siren-ui/core/recording";
import { decibelsToAmplitude } from "@siren-ui/core/waveform";
import { useCallback, useEffect, useMemo, useSyncExternalStore } from "react";
import {
  AudioModule,
  RecordingPresets,
  setAudioModeAsync,
  useAudioRecorder,
  useAudioRecorderState,
} from "expo-audio";

export type UseExpoVoiceRecorderOptions = {
  minimumDurationMs?: number;
  maximumDurationMs?: number;
  requestPermissionOnStart?: boolean;
  onComplete?: (recording: SirenRecording) => void;
  onError?: (error: SirenRecorderError) => void;
};

export function useExpoVoiceRecorder(
  options: UseExpoVoiceRecorderOptions = {},
) {
  const recorder = useAudioRecorder(RecordingPresets.HIGH_QUALITY);
  const recorderState = useAudioRecorderState(recorder, 100);
  const controller = useMemo(
    () =>
      new RecorderController({
        minimumDurationMs: options.minimumDurationMs,
        maximumDurationMs: options.maximumDurationMs,
      }),
    [options.maximumDurationMs, options.minimumDurationMs],
  );
  const snapshot = useSyncExternalStore(
    controller.subscribe,
    controller.getSnapshot,
    controller.getSnapshot,
  );
  useEffect(() => {
    if (snapshot.error) options.onError?.(snapshot.error);
  }, [options, snapshot.error]);
  useEffect(() => {
    if (snapshot.state === "recording" || snapshot.state === "locked")
      controller.tick();
  }, [controller, recorderState.durationMillis, snapshot.state]);
  useEffect(
    () => () => {
      if (recorderState.isRecording) void recorder.stop();
    },
    [recorder, recorderState.isRecording],
  );

  const start = useCallback(async () => {
    try {
      const permission = await AudioModule.getRecordingPermissionsAsync();
      if (!permission.granted) {
        if (!options.requestPermissionOnStart) {
          controller.requestPermission();
          controller.permissionResolved(false, permission.canAskAgain);
          return;
        }
        controller.requestPermission();
        const requested = await AudioModule.requestRecordingPermissionsAsync();
        if (!requested.granted) {
          controller.permissionResolved(false, requested.canAskAgain);
          return;
        }
      }
      await setAudioModeAsync({
        allowsRecording: true,
        playsInSilentMode: true,
        interruptionMode: "doNotMix",
      });
      await recorder.prepareToRecordAsync();
      recorder.record();
      controller.start();
    } catch (cause) {
      controller.unavailable(cause);
    }
  }, [controller, options.requestPermissionOnStart, recorder]);

  const stop = useCallback(async () => {
    try {
      controller.process();
      await recorder.stop();
      const uri = recorder.uri;
      if (!uri) throw new Error("expo-audio did not return a recording URI");
      const recording = controller.complete({
        uri,
        durationMs: recorderState.durationMillis,
      });
      if (recording) options.onComplete?.(recording);
    } catch (cause) {
      controller.interrupt(recorder.uri ?? undefined, cause);
    }
  }, [controller, options, recorder, recorderState.durationMillis]);

  const cancel = useCallback(async () => {
    try {
      if (recorderState.isRecording) await recorder.stop();
    } finally {
      controller.cancel();
    }
  }, [controller, recorder, recorderState.isRecording]);
  const pause = useCallback(async () => {
    recorder.pause();
    controller.pause();
  }, [controller, recorder]);
  const resume = useCallback(async () => {
    recorder.record();
    controller.resume();
  }, [controller, recorder]);
  const lock = useCallback(() => controller.lock(), [controller]);
  return {
    snapshot: {
      ...snapshot,
      durationMs: recorderState.durationMillis,
    } as RecorderSnapshot,
    sample: decibelsToAmplitude(recorderState.metering ?? -60),
    start,
    stop,
    cancel,
    pause,
    resume,
    lock,
    reset: controller.reset.bind(controller),
  };
}

import type { ReactNode } from "react";
import {
  Pressable,
  type PressableProps,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import Animated, {
  interpolate,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import { shouldReduceMotion, sirenPressIn, sirenStateSpring } from "../motion";

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

export type MotionPressableProps = Omit<
  PressableProps,
  "children" | "style"
> & {
  children: ReactNode;
  style?: StyleProp<ViewStyle>;
  pressedScale?: number;
  reducedMotion?: boolean;
};

export function MotionPressable({
  children,
  disabled,
  hitSlop = 8,
  onPressIn,
  onPressOut,
  pressedScale = 0.96,
  reducedMotion,
  style,
  ...props
}: MotionPressableProps) {
  const systemReducedMotion = useReducedMotion();
  const reduce = shouldReduceMotion(reducedMotion, systemReducedMotion);
  const pressed = useSharedValue(0);
  const animatedStyle = useAnimatedStyle(() => ({
    opacity: interpolate(pressed.get(), [0, 1], [1, 0.82]),
    transform: [
      {
        scale: reduce
          ? 1
          : interpolate(pressed.get(), [0, 1], [1, pressedScale]),
      },
    ],
  }));

  return (
    <AnimatedPressable
      {...props}
      accessibilityRole={props.accessibilityRole ?? "button"}
      disabled={disabled}
      hitSlop={hitSlop}
      onPressIn={(event) => {
        pressed.set(withTiming(1, sirenPressIn));
        onPressIn?.(event);
      }}
      onPressOut={(event) => {
        pressed.set(withSpring(0, sirenStateSpring));
        onPressOut?.(event);
      }}
      style={[style, disabled && { opacity: 0.46 }, animatedStyle]}
    >
      {children}
    </AnimatedPressable>
  );
}

import { Easing, ReduceMotion } from "react-native-reanimated";

/** Strong ease-out used for immediate, non-physical feedback. */
export const sirenEaseOut = Easing.bezier(0.23, 1, 0.32, 1);

/** Press-in is deliberately faster than the spring-backed release. */
export const sirenPressIn = {
  duration: 120,
  easing: sirenEaseOut,
  reduceMotion: ReduceMotion.System,
} as const;

/** Critically damped state transition: responsive without decorative bounce. */
export const sirenStateSpring = {
  duration: 300,
  dampingRatio: 1,
  reduceMotion: ReduceMotion.System,
} as const;

/** Momentum is reserved for gestures that were moving at release. */
export const sirenGestureSpring = {
  duration: 300,
  dampingRatio: 0.8,
  reduceMotion: ReduceMotion.System,
} as const;

export function shouldReduceMotion(
  explicit: boolean | undefined,
  system: boolean,
) {
  return explicit ?? system;
}

